//! Lennard-Jones splined term comparisons against the exact-source library.
//! Generated by tools/rust_port/validate_ljs.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::ljs::LjsBh;

const ATOL: f64 = 1.0e-12;
const RTOL: f64 = 1.0e-10;

#[test]
fn ljs_terms_match_the_source() {
    let model = LjsBh::new();
    let mut checked = 0;
    for row in include_str!("fixtures/ljs.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let reduced_temperature: f64 = parts[0].parse().unwrap();
        let reduced_density: f64 = parts[1].parse().unwrap();
        let source: Vec<f64> = fields[1..].iter().map(|v| v.parse().unwrap()).collect();
        let (first, second, third) = model
            .reduced_perturbation_terms(reduced_temperature, reduced_density)
            .unwrap();
        let diameter = model.diameter_div_sigma(reduced_temperature).unwrap();
        let native = [first, second, third, diameter];
        assert_eq!(native.len(), source.len(), "{case}");
        for (position, (source, native)) in source.iter().zip(native.iter()).enumerate() {
            assert!(
                (source - native).abs() <= ATOL + RTOL * source.abs(),
                "{case} entry {position}: source {source} native {native}"
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 8);
}

#[test]
fn the_spline_polynomials_match_the_source() {
    let model = LjsBh::new();
    let mut checked = 0;
    for row in include_str!("fixtures/ljs_spline.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let reduced_temperature: f64 = parts[0].parse().unwrap();
        let reduced_density: f64 = parts[1].parse().unwrap();
        let index: usize = parts[2].parse().unwrap();
        let source: Vec<f64> = fields[1..].iter().map(|v| v.parse().unwrap()).collect();
        let native = model
            .spline_polynomial(index, reduced_temperature, reduced_density)
            .unwrap();
        let native = [native.0, native.1, native.2, native.3, native.4, native.5];
        assert_eq!(native.len(), source.len(), "{case}");
        for (position, (source, native)) in source.iter().zip(native.iter()).enumerate() {
            assert!(
                (source - native).abs() <= ATOL + RTOL * source.abs(),
                "{case} entry {position}: source {source} native {native}"
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 8);
}

#[test]
fn the_diameter_is_close_to_the_segment_diameter() {
    // The Barker-Henderson diameter of the argon record of the source is
    // close to its segment diameter over the reduced temperature range.
    let model = LjsBh::new();
    for reduced_temperature in [0.4, 0.8, 1.2, 1.6] {
        let diameter = model.diameter_div_sigma(reduced_temperature).unwrap();
        assert!(
            diameter > 0.9 && diameter < 1.0,
            "{reduced_temperature}: {diameter}"
        );
    }
}

#[test]
fn the_parameters_can_be_replaced() {
    // The source allows the segment diameter and the well depth of the model
    // to be replaced.
    let model = LjsBh::with_parameters(3.5e-10, 120.0);
    assert!((model.sigma() - 3.5e-10).abs() < 1.0e-16);
    assert!((model.eps() - 120.0).abs() < 1.0e-12);
    let terms = model.reduced_perturbation_terms(1.0, 0.5).unwrap();
    assert!(terms.0.is_finite() && terms.1.is_finite() && terms.2.is_finite());
}
